import java.util.Scanner;

public class Main {
    static int n, k, p;
    static int[][] memoTable = new int[30][250005];
    static int[] factArr = new int[250005];
    static int[] invFactArr = new int[250005];

    static int powerMod(int base, int exp) {
        long result = 1;
        long current = base;
        while (exp > 0) {
            if ((exp & 1) == 1) {
                result = (result * current) % p;
            }
            current = (current * current) % p;
            exp >>= 1;
        }
        return (int) result;
    }

    static int getLowbit(int x) {
        return x & (-x);
    }

    static void prepareFactorials() {
        factArr[0] = 1;
        for (int i = 1; i <= n; i++) {
            factArr[i] = (int) ((long) factArr[i - 1] * i % p);
        }
        invFactArr[n] = powerMod(factArr[n], p - 2);
        for (int i = n; i >= 1; i--) {
            invFactArr[i - 1] = (int) ((long) invFactArr[i] * i % p);
        }
    }

    static int recursive(int idx, int mask) {
        if (memoTable[idx][mask] != -1)
            return memoTable[idx][mask];
        if (mask == 0) {
            int res = factArr[n];
            for (int i = 1; i <= idx; i++)
                res = (int) ((long) res * (k - i + 1) % p);
            return memoTable[idx][mask] = res;
        }
        int total = 0;
        int rem = mask - getLowbit(mask);
        for (int subset = rem; subset != 0; subset = (subset - 1) & rem) {
            total = (int) ((total + (long) invFactArr[mask - subset] * recursive(idx + 1, subset)) % p);
        }
        total = (int) ((total + (long) invFactArr[mask] * recursive(idx + 1, 0)) % p);
        return memoTable[idx][mask] = total;
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        n = sc.nextInt();
        k = sc.nextInt();
        p = sc.nextInt();

        for (int i = 0; i < 30; i++) {
            for (int j = 0; j < 250005; j++) {
                memoTable[i][j] = -1;
            }
        }

        int ans = 1;
        for (int i = 1; i <= n; i++) {
            ans = (int) ((long) ans * k % p);
        }

        if (n % 2 == 0) {
            prepareFactorials();
            ans = (ans - recursive(0, n) + p) % p;
        }

        System.out.println(ans);
        sc.close();
    }
}
